export const techdeckResolutionRelationships = pgTable('techdeck_resolution_relationships', {
  id: varchar('id', { length: 36 }).primaryKey().default(sql`gen_random_uuid()`),
  tenantId: varchar('tenant_id', { length: 36 }).notNull(),
  incidentId: varchar('incident_id', { length: 36 }).notNull(),
  revision: integer('revision').notNull(),
  sourcePointer: varchar('source_pointer', { length: 1024 }).notNull(),
  sourceNodeId: varchar('source_node_id', { length: 36 }).notNull(),
  targetNodeId: varchar('target_node_id', { length: 36 }).notNull(),
  sourceKind: varchar('source_kind', { length: 32 }).notNull(),
  targetKind: varchar('target_kind', { length: 32 }).notNull(),
  relationshipType: varchar('relationship_type', { length: 32 }).notNull(),
  evidenceLinkId: varchar('evidence_link_id', { length: 36 }),
  algorithmVersion: varchar('algorithm_version', { length: 40 }),
  score: numeric('score'),
  claimKind: text('claim_kind').notNull().default("reported_fact"),
  confidence: text('confidence'),
  createdByUserId: varchar('created_by_user_id', { length: 36 }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t): PgTableExtraConfigValue[] => [
  foreignKey({ name: 'tdri_relationships_tenant_id_fk', columns: [t.tenantId], foreignColumns: [tenants.id] }).onDelete('cascade'),
  check('tdri_relationships_revision_ck', sql.raw("revision > 0")),
  check('tdri_relationships_source_pointer_ck', sql.raw("octet_length(source_pointer) <= 1024 AND (source_pointer = '' OR source_pointer ~ '^/([^~]|~[01])*$')")),
  check('tdri_relationships_score_ck', sql.raw("score >= 0 AND score <= 1")),
  check('tdri_relationships_claim_kind_ck', sql.raw("claim_kind IN ('reported_fact','supported_conclusion','hypothesis','unverified','pending_validation')")),
  check('tdri_relationships_confidence_ck', sql.raw("confidence IN ('CONFIRMED','HIGH','MODERATE','LOW','UNKNOWN')")),
  foreignKey({ name: 'tdri_relationships_created_by_user_id_fk', columns: [t.createdByUserId], foreignColumns: [users.id] }).onDelete('set null'),
  unique('tdri_relationships_tenant_uq').on(t.tenantId, t.id),
  foreignKey({ name: 'tdri_relationships_revision_fk', columns: [t.tenantId, t.incidentId, t.revision], foreignColumns: [techdeckResolutionRawExports.tenantId, techdeckResolutionRawExports.incidentId, techdeckResolutionRawExports.revision] }).onDelete('cascade'),
  unique('tdri_relationships_revision_id_uq').on(t.tenantId, t.incidentId, t.revision, t.id),
  check('tdri_relationships_claim_kind_len', sql.raw("octet_length(claim_kind) <= 100000")),
  check('tdri_relationships_confidence_len', sql.raw("octet_length(confidence) <= 100000")),
  foreignKey({ name: 'tdri_relationships_source_fk', columns: [t.tenantId, t.incidentId, t.revision, t.sourceNodeId, t.sourceKind], foreignColumns: [techdeckResolutionNodes.tenantId, techdeckResolutionNodes.incidentId, techdeckResolutionNodes.revision, techdeckResolutionNodes.id, techdeckResolutionNodes.kind] }).onDelete('cascade'),
  foreignKey({ name: 'tdri_relationships_target_fk', columns: [t.tenantId, t.targetNodeId, t.targetKind], foreignColumns: [techdeckResolutionNodes.tenantId, techdeckResolutionNodes.id, techdeckResolutionNodes.kind] }).onDelete('cascade'),
  foreignKey({ name: 'tdri_relationships_evidence_link_fk', columns: [t.tenantId, t.incidentId, t.revision, t.evidenceLinkId], foreignColumns: [techdeckResolutionEvidenceLinks.tenantId, techdeckResolutionEvidenceLinks.incidentId, techdeckResolutionEvidenceLinks.revision, techdeckResolutionEvidenceLinks.id] }),
  check('tdri_relationships_type_ck', sql.raw("(relationship_type='INDICATES' AND source_kind='symptom' AND target_kind='root_cause') OR (relationship_type='ASSOCIATED_WITH' AND source_kind='error' AND target_kind='component') OR (relationship_type='RESOLVED' AND source_kind='action' AND target_kind='incident') OR (relationship_type='FAILED_FOR' AND source_kind='action' AND target_kind='incident') OR (relationship_type='CAUSED_SIDE_EFFECT' AND source_kind='action' AND target_kind='side_effect') OR (relationship_type='FOLLOWED_BY' AND source_kind='action' AND target_kind='side_effect') OR (relationship_type='RECOVERED_BY' AND source_kind='side_effect' AND target_kind='action') OR (relationship_type='AFFECTS' AND source_kind='root_cause' AND target_kind='component') OR (relationship_type='SIMILAR_TO' AND source_kind='incident' AND target_kind='incident') OR (relationship_type='OCCURRED_ON' AND source_kind='incident' AND target_kind='device') OR (relationship_type='GENERATED' AND source_kind='incident' AND target_kind='kb') OR (relationship_type='SUGGESTS_AUTOMATION' AND source_kind='incident' AND target_kind='automation') OR (relationship_type='SUPPORTED_BY' AND source_kind='root_cause' AND target_kind='evidence')")),
  check('tdri_relationships_self_ck', sql.raw("source_node_id <> target_node_id")),
  check('tdri_relationships_causal_ck', sql.raw("relationship_type <> 'CAUSED_SIDE_EFFECT' OR (claim_kind='supported_conclusion' AND confidence IS NOT NULL AND confidence IN ('CONFIRMED','HIGH') AND evidence_link_id IS NOT NULL)")),
  unique('tdri_relationships_edge_uq').on(t.tenantId, t.sourceNodeId, t.targetNodeId, t.relationshipType),
  index('tdri_relationships_incident_idx').on(sql.raw("tenant_id"), sql.raw("incident_id"), sql.raw("revision")),
  index('tdri_relationships_source_idx').on(sql.raw("tenant_id"), sql.raw("source_node_id"), sql.raw("relationship_type")),
  index('tdri_relationships_target_idx').on(sql.raw("tenant_id"), sql.raw("target_node_id"), sql.raw("relationship_type")),
]);
